const detail = $handlers.story_get({ storyId: "B-9c2c", detail: true });
const item = detail.checklist.items.find((i) => i.id === "CHK-001");
const fx = item.testIntent.happy[0].fixture;
if (!fx || fx.file !== "story-get-fixture-mapping.json" || fx.name !== "story_get maps scoped current-story fixture" || !(fx.line > 0)) {
  throw new Error("scoped fixture mismatch: " + JSON.stringify(fx));
}
return { ok: true, mapped: fx.name, file: fx.file };

